(function () {
    function activateProxyFallback(video) {
        const proxySrc = video.getAttribute('data-proxy-src');
        const source = video.querySelector('source');
        if (!proxySrc || !source) { return; }
        let switched = false;
        function switchToProxy() {
            if (switched || (source.getAttribute('src') || '').indexOf('proxy=1') !== -1) { return; }
            switched = true;
            source.setAttribute('src', proxySrc);
            // Bei falsch erkannten Server-MIME-Typen soll der Browser selbst prüfen.
            source.removeAttribute('type');
            const note = video.parentElement ? video.parentElement.querySelector('.glma-video-fallback-note') : null;
            if (note) { note.classList.remove('d-none'); }
            video.load();
        }
        video.addEventListener('error', switchToProxy, true);
        source.addEventListener('error', switchToProxy);
        // Einige Browser melden fehlgeschlagene <source>-Loads nur über networkState.
        window.setTimeout(function () {
            if (video.networkState === HTMLMediaElement.NETWORK_NO_SOURCE) {
                switchToProxy();
            }
        }, 2500);
    }
    document.querySelectorAll('video.glma-preview-video[data-proxy-src]').forEach(activateProxyFallback);
})();

(function () {
    const maxFiles = 50;
    const maxSize = 200 * 1024 * 1024;
    const chunkSize = 5 * 1024 * 1024;
    const parallelUploads = 2;
    const folderSelect = document.getElementById('glma_folder_select');
    const fileInput = document.getElementById('glma_file_input');
    const startButton = document.getElementById('glma_upload_start');
    const csrfInput = document.getElementById('glma_csrf');
    const log = document.getElementById('glma_upload_log');
    const statusBox = document.getElementById('glma_upload_status');
    const totalBar = document.getElementById('glma_upload_total_bar');
    const reviewerWarning = document.getElementById('glma_reviewer_warning');

    function setStatus(message, kind) {
        statusBox.className = 'alert mt-3 alert-' + (kind || 'info');
        statusBox.textContent = message;
        statusBox.classList.remove('d-none');
    }

    function addLogItem(file) {
        const item = document.createElement('div');
        item.className = 'list-group-item';
        item.innerHTML = '<div class="d-flex justify-content-between"><strong></strong><span class="badge bg-secondary">wartet</span></div><div class="progress mt-2" style="height: 10px;"><div class="progress-bar" style="width:0%"></div></div><div class="small text-muted mt-1"></div>';
        item.querySelector('strong').textContent = file.name;
        log.appendChild(item);
        return item;
    }

    function setItem(item, percent, badge, badgeClass, detail) {
        const bar = item.querySelector('.progress-bar');
        const badgeNode = item.querySelector('.badge');
        const detailNode = item.querySelector('.small');
        bar.style.width = Math.max(0, Math.min(100, percent || 0)) + '%';
        badgeNode.className = 'badge ' + (badgeClass || 'bg-secondary');
        badgeNode.textContent = badge || 'wartet';
        detailNode.textContent = detail || '';
    }

    function postChunk(form, onProgress) {
        return new Promise((resolve) => {
            const xhr = new XMLHttpRequest();
            xhr.open('POST', '/media-approval/backend/upload-chunk', true);
            xhr.upload.onprogress = function (event) {
                if (event.lengthComputable && onProgress) {
                    onProgress(event.loaded, event.total);
                }
            };
            xhr.onload = function () {
                let payload = null;
                try { payload = JSON.parse(xhr.responseText || '{}'); } catch (e) {}
                if (xhr.status >= 200 && xhr.status < 300 && payload && payload.ok) {
                    resolve({ok: true, payload: payload});
                } else {
                    const error = payload && payload.error ? payload.error : ('HTTP ' + xhr.status);
                    resolve({ok: false, error: error});
                }
            };
            xhr.onerror = function () {
                resolve({ok: false, error: 'Netzwerkfehler beim Upload.'});
            };
            xhr.send(form);
        });
    }

    async function uploadOne(file, item, folderId) {
        const uploadUid = String(Date.now()) + '_' + Math.random().toString(36).slice(2) + '_' + file.name.replace(/[^a-zA-Z0-9_.-]/g, '_');
        const totalChunks = Math.max(1, Math.ceil(file.size / chunkSize));
        let finalPayload = null;
        setItem(item, 0, 'startet', 'bg-primary', 'Upload wird vorbereitet...');
        for (let chunkIndex = 0; chunkIndex < totalChunks; chunkIndex++) {
            const start = chunkIndex * chunkSize;
            const end = Math.min(file.size, start + chunkSize);
            const blob = file.slice(start, end);
            const form = new FormData();
            form.append('csrf_token', csrfInput.value);
            form.append('folder_id', folderId);
            form.append('upload_uid', uploadUid);
            form.append('filename', file.name);
            form.append('mimetype', file.type || 'application/octet-stream');
            form.append('total_size', String(file.size));
            form.append('chunk_index', String(chunkIndex));
            form.append('total_chunks', String(totalChunks));
            form.append('chunk', blob, file.name + '.part' + chunkIndex);
            const result = await postChunk(form, function (loaded, total) {
                const uploadedBefore = start;
                const current = uploadedBefore + loaded;
                const percent = file.size ? Math.round((current / file.size) * 100) : 100;
                setItem(item, percent, 'lädt hoch', 'bg-primary', 'Teil ' + (chunkIndex + 1) + '/' + totalChunks + ' · ' + Math.round(current / 1024 / 1024) + ' MB / ' + Math.round(file.size / 1024 / 1024) + ' MB');
            });
            if (!result.ok) {
                setItem(item, 100, 'Fehler', 'bg-danger', result.error || 'Upload fehlgeschlagen.');
                return {ok: false, error: result.error};
            }
            finalPayload = result.payload;
        }
        setItem(item, 100, 'fertig', 'bg-success', 'Übertragen als: ' + ((finalPayload && finalPayload.name) || file.name));
        return {ok: true};
    }

    function updateTotal(done, total) {
        const percent = total ? Math.round((done / total) * 100) : 0;
        totalBar.style.width = percent + '%';
        totalBar.textContent = percent + '%';
    }

    function selectedReviewerCount() {
        const option = folderSelect.options[folderSelect.selectedIndex];
        return option ? parseInt(option.getAttribute('data-reviewer-count') || '0', 10) : 0;
    }

    function updateReviewerWarning() {
        if (!folderSelect.value || selectedReviewerCount() > 0) {
            reviewerWarning.classList.add('d-none');
        } else {
            reviewerWarning.classList.remove('d-none');
        }
    }

    folderSelect.addEventListener('change', updateReviewerWarning);
    updateReviewerWarning();

    startButton.addEventListener('click', async function () {
        const folderId = folderSelect.value;
        const files = Array.from(fileInput.files || []);
        log.innerHTML = '';
        updateTotal(0, 0);
        if (!folderId) {
            setStatus('Bitte zuerst einen Unterordner auswählen.', 'warning');
            return;
        }
        if (selectedReviewerCount() <= 0) {
            updateReviewerWarning();
            setStatus('Bitte zuerst im Unterordner mindestens eine bewertende Person mit 6-stelliger PIN hinterlegen.', 'warning');
            return;
        }
        if (!files.length) {
            setStatus('Bitte mindestens eine Datei auswählen.', 'warning');
            return;
        }
        if (files.length > maxFiles) {
            setStatus('Bitte maximal ' + maxFiles + ' Dateien pro Durchlauf auswählen.', 'danger');
            return;
        }
        const tooLarge = files.filter((file) => file.size > maxSize);
        if (tooLarge.length) {
            setStatus('Mindestens eine Datei ist größer als 200 MB: ' + tooLarge.map((f) => f.name).join(', '), 'danger');
            return;
        }
        startButton.disabled = true;
        fileInput.disabled = true;
        folderSelect.disabled = true;
        setStatus('Upload läuft. Bitte dieses Fenster nicht schließen.', 'info');
        const queue = files.map((file) => ({file: file, item: addLogItem(file)}));
        let done = 0;
        let ok = 0;
        let failed = 0;
        updateTotal(0, queue.length);

        async function worker() {
            while (queue.length) {
                const next = queue.shift();
                const result = await uploadOne(next.file, next.item, folderId);
                done += 1;
                if (result.ok) { ok += 1; } else { failed += 1; }
                updateTotal(done, files.length);
            }
        }
        const workers = [];
        for (let i = 0; i < Math.min(parallelUploads, files.length); i++) {
            workers.push(worker());
        }
        await Promise.all(workers);
        startButton.disabled = false;
        fileInput.disabled = false;
        folderSelect.disabled = false;
        if (failed) {
            setStatus('Upload abgeschlossen: ' + ok + ' erfolgreich, ' + failed + ' fehlgeschlagen.', 'warning');
        } else {
            setStatus('Upload abgeschlossen: ' + ok + ' Dateien erfolgreich übertragen.', 'success');
        }
    });
})();
